<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref} from 'vue';
import AdminSearchSelect from '../components/AdminSearchSelect.vue';
import PromoterIcon from '../PromoterIcon.vue';
import {units4,decimal4} from '../portalAmounts';
import {ApiError} from '../api';
import * as api from './agentIncome';
import type {IncomeRow,IncomePage,IncomePayout} from './agentIncome';
import './agent-income.css';
const month=ref(new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit'}).format(new Date()));
const status=ref('ALL'),owner=ref(''),page=ref(0),size=ref(10),snapshot=ref<IncomePage>(),previousSnapshot=ref<IncomePage>(),loading=ref(false),error=ref(''),busy=ref(false);
const historicalRates=ref<(string|null)[]>([]);let rateRevision=0;
const currentRates=ref<Record<string,string|null>>({});
const people=ref<Record<string,{nickname?:string|null;phone?:string|null}>>({});
const options=ref<{value:string;label:string;detail?:string}[]>([]),searching=ref(false),searchMore=ref(false);let searchPage=0,query='';
const selected=ref<IncomeRow>(),tab=ref('settlement'),detailPage=ref(0),detailTotal=ref(0),detailLoading=ref(false),detailError=ref('');
const consumptionRows=ref<Awaited<ReturnType<typeof api.consumptions>>['items']>([]),adjustmentRows=ref<Awaited<ReturnType<typeof api.adjustments>>['items']>([]),historyRows=ref<Awaited<ReturnType<typeof api.payoutHistory>>['items']>([]);
const fullAccount=ref<Awaited<ReturnType<typeof api.accountDetails>>>();
const modal=ref<HTMLDialogElement>(),mode=ref(''),formError=ref(''),amount=ref(''),reason=ref(''),accountId=ref(''),reference=ref(''),paidAt=ref('');
const accountRows=ref<Awaited<ReturnType<typeof api.accounts>>['items']>([]),accountPage=ref(0),accountTotal=ref(0);
let alive=true,revision=0,detailRevision=0,searchRevision=0;let trigger:HTMLElement|undefined;
const draftWithdrawalId=ref(''),direction=ref('add');
const incomeDraft=ref<Awaited<ReturnType<typeof api.incomeDraft>>>(),draftLoading=ref(false);let draftRevision=0;
const adjustmentAmount=computed(()=>selectedPayout.value?.adjustmentAmount4??incomeDraft.value?.adjustmentAmount4);
const baseAmount=computed(()=>selectedPayout.value?.baseAmount4??selected.value?.commissionAmount4);
function addAmounts(a?:string|null,b?:string|null){const x=units4(a),y=units4(b);return x===null||y===null?null:decimal4(x+y);}
const finalAmount=computed(()=>selectedPayout.value?.finalAmount4??addAmounts(baseAmount.value,adjustmentAmount.value));
const canAdjust=computed(()=>selectedPayout.value?selectedPayout.value.status==='WITHDRAWING'&&!!selectedPayout.value.settlementMonth:selected.value?.promoterStatus==='ENABLED'&&month.value!=='UNASSIGNED'&&!!incomeDraft.value&&!draftLoading.value);
const nextAdjustment=computed(()=>{const n=units4(amount.value),current=units4(adjustmentAmount.value);return n===null||current===null?null:decimal4(current+(direction.value==='subtract'?-n:n));});
const adjustmentPreview=computed(()=>addAmounts(baseAmount.value,nextAdjustment.value));
const createPreview=computed(()=>addAmounts(amount.value,selectedPayout.value?'0.0000':incomeDraft.value?.adjustmentAmount4));
async function loadDraft(row:IncomeRow){const run=++draftRevision;incomeDraft.value=undefined;draftLoading.value=false;if(row.payout||month.value==='UNASSIGNED')return;draftLoading.value=true;try{const result=await api.incomeDraft(row.promoterUserId,month.value);if(alive&&run===draftRevision)incomeDraft.value=result;}catch{if(alive&&run===draftRevision)detailError.value='调整记录读取失败，请重新打开详情后重试';}finally{if(alive&&run===draftRevision)draftLoading.value=false;}}

const pending=new Map<string,Record<string,unknown>>();
onUnmounted(()=>{alive=false;draftRevision++;rateRevision++;revision++;detailRevision++;searchRevision++;pending.clear();});
const statuses=[['ALL','全部代理'],['UNSETTLED','待结算'],['WITHDRAWING','待审核'],['PENDING_PAYOUT','待发放'],['PAID','已发放'],['REJECTED','异常']];
const statusName=(value:string)=>statuses.find(s=>s[0]===value)?.[1]||value;
const tabs=[['settlement','结算详情'],['consumption','消费明细'],['adjustments','调整记录'],['payments','发放记录']];
const entryId=ref('');
const selectedPayout=computed(()=>selected.value?.payout);
const count=(key:string)=>key==='ALL'?snapshot.value?.statusTotals?.reduce((n,s)=>n+s.count,0)||0:snapshot.value?.statusTotals?.find(s=>s.status===key)?.count||0;
const name=(id:string)=>people.value[id]?.nickname||id;
const phone=(id:string)=>people.value[id]?.phone?.replace(/^\+86/,'').replace(/^(\d{3})\d+(\d{4})$/,'$1****$2')||'—';
function percent(value?:string|null){return value==null||!value.trim()||!Number.isFinite(Number(value))||Number(value)<0||Number(value)>1?'—':`${Number((Number(value)*100).toFixed(4))}%`;}
const rate=(id:string)=>percent(currentRates.value[id]);
const historicalRateText=computed(()=>historicalRates.value.length?historicalRates.value.map(percent).join(' / '):'—');
function money(value?:string|null){const n=units4(value);if(n===null)return '—';const a=n<0n?-n:n;return `${n<0n?'- ':''}¥ ${(a/10000n).toLocaleString('en-US')}.${String(a%10000n/100n).padStart(2,'0')}`;}
const date=(v?:string|null)=>v?new Date(v).toLocaleString('sv-SE',{timeZone:'Asia/Shanghai',hour12:false}):'—';
const totalPages=computed(()=>Math.max(1,Math.ceil((snapshot.value?.total||0)/size.value)));
const pages=computed(()=>Array.from(new Set([0,page.value-1,page.value,page.value+1,totalPages.value-1])).filter(p=>p>=0&&p<totalPages.value).sort((a,b)=>a-b));
async function identities(ids:string[]){await Promise.all([...new Set(ids)].filter(id=>!people.value[id]).map(async id=>{try{const result=await api.identity(id);if(alive)people.value[id]=result;}catch{if(alive)people.value[id]={nickname:id};}}));}
function previousMonth(value:string){const [y,m]=value.split('-').map(Number);return `${String(m===1?y!-1:y!).padStart(4,'0')}-${String(m===1?12:m!-1).padStart(2,'0')}`;}
const consumptionChange=computed(()=>{const current=units4(snapshot.value?.totalConsumptionAmount4),previous=units4(previousSnapshot.value?.totalConsumptionAmount4);if(current===null||previous===null||previous===0n)return '—';const change=(current-previous)*10000n/previous,absolute=change<0n?-change:change,fraction=String(absolute%100n).padStart(2,'0').replace(/0+$/,'');return `${change<0n?'-':'+'}${absolute/100n}${fraction?'.'+fraction:''}%`;});
const unsettledChange=computed(()=>{if(!snapshot.value||!previousSnapshot.value)return '—';const difference=count('UNSETTLED')-(previousSnapshot.value.statusTotals.find(s=>s.status==='UNSETTLED')?.count||0);return `${difference>0?'+':''}${difference}`;});
const changeClass=(value:string)=>value.startsWith('-')?'decrease':value.startsWith('+')&&value!=='+0%'?'increase':'';
async function load(next=0){const run=++revision;loading.value=true;snapshot.value=undefined;previousSnapshot.value=undefined;currentRates.value={};error.value='';const query={month:month.value,status:status.value,promoterUserId:owner.value||undefined,page:next,size:size.value};try{const [result,previous]=await Promise.all([api.loadIncome(query),query.month==='UNASSIGNED'?Promise.resolve(undefined):api.loadIncome({...query,month:previousMonth(query.month),status:'ALL',page:0,size:1}).catch(()=>undefined)]);if(!alive||run!==revision)return;snapshot.value=result;previousSnapshot.value=previous;page.value=next;await Promise.all([identities(result.items.map(r=>r.promoterUserId)),...Array.from(new Set(result.items.map(r=>r.promoterUserId))).map(async id=>{const value=await api.currentRate(id).catch(()=>null);if(alive&&run===revision)currentRates.value[id]=value;})]);}catch{if(alive&&run===revision)error.value='代理收益加载失败，请重试';}finally{if(alive&&run===revision)loading.value=false;}}

async function searchAgents(text='',more=false){const run=++searchRevision;searching.value=true;if(!more){searchPage=0;query=text;}try{const result=await api.searchAgents(query,searchPage);if(!alive||run!==searchRevision)return;options.value=more?[...options.value,...result.items]:result.items;searchPage++;searchMore.value=searchPage*20<result.total;}catch{if(alive)error.value='代理搜索失败，请重试';}finally{if(alive&&run===searchRevision)searching.value=false;}}
function closeDetail(){if(busy.value)return;selected.value=undefined;draftRevision++;incomeDraft.value=undefined;rateRevision++;historicalRates.value=[];detailRevision++;fullAccount.value=undefined;trigger?.focus();}
async function loadHistoricalRates(row:IncomeRow){const run=++rateRevision;historicalRates.value=[];try{const rates=await api.historicalRates(row.promoterUserId,month.value);if(alive&&run===rateRevision)historicalRates.value=rates;}catch{/* Unknown historical rates remain unavailable. */}}
async function open(row:IncomeRow,event:Event){if(busy.value)return;trigger=event.currentTarget as HTMLElement;selected.value=row;void loadHistoricalRates(row);consumptionRows.value=[];adjustmentRows.value=[];historyRows.value=[];detailTotal.value=0;detailLoading.value=false;entryId.value='';fullAccount.value=undefined;tab.value='settlement';detailError.value='';detailRevision++;void loadDraft(row);await nextTick();document.getElementById('income-close-detail')?.focus({preventScroll:true});try{const id=await api.credentialFor(row.promoterUserId);if(alive&&selected.value?.promoterUserId===row.promoterUserId)entryId.value=id;}catch{/* No usable portal login for this account. */}}
async function switchTab(value:string,next=0){consumptionRows.value=[];adjustmentRows.value=[];historyRows.value=[];detailTotal.value=0;tab.value=value;detailPage.value=next;detailError.value='';const row=selected.value,run=++detailRevision;if(!row||value==='settlement')return;detailLoading.value=true;try{if(value==='consumption'){const result=await api.consumptions(row.promoterUserId,month.value,next);if(!alive||run!==detailRevision)return;consumptionRows.value=result.items;detailTotal.value=result.total;await identities(result.items.map(r=>r.customerUserId));}else if(value==='adjustments'){const result=row.payout?await api.adjustments(row.payout.id,next):month.value==='UNASSIGNED'?{items:[],total:0}:(await api.incomeDraft(row.promoterUserId,month.value,next)).adjustments;if(!alive||run!==detailRevision)return;adjustmentRows.value=result.items;detailTotal.value=result.total;await identities(result.items.map(r=>r.operatorId));}else{const result=await api.payoutHistory(row.promoterUserId,next);if(!alive||run!==detailRevision)return;historyRows.value=result.items;detailTotal.value=result.total;}}catch{if(alive&&run===detailRevision)detailError.value='详情读取失败，请重试';}finally{if(alive&&run===detailRevision)detailLoading.value=false;}}
async function reveal(){if(!selectedPayout.value||busy.value)return;busy.value=true;const id=selectedPayout.value.id;try{const result=await api.accountDetails(id);if(alive&&selectedPayout.value?.id===id)fullAccount.value=result;}catch{if(alive)detailError.value='收款账户读取失败，请重试';}finally{if(alive)busy.value=false;}}
async function enter(){if(!entryId.value||busy.value)return;busy.value=true;try{await api.enterAgent(entryId.value);}catch{if(alive)detailError.value='进入代理后台失败，请确认代理已有启用的登录账号';}finally{if(alive)busy.value=false;}}
async function loadAccounts(more=false){const row=selected.value;if(!row)return;const next=more?accountPage.value+1:0;try{const result=await api.accounts(row.promoterUserId,next);if(!alive||selected.value?.promoterUserId!==row.promoterUserId)return;accountRows.value=more?[...accountRows.value,...result.items]:result.items;accountPage.value=next;accountTotal.value=result.total;}catch{if(alive)formError.value='收款账户读取失败，请重试';}}
async function openModal(value:string){if(value==='adjust'&&!canAdjust.value||value==='create'&&!selectedPayout.value&&!incomeDraft.value)return;direction.value='add';mode.value=value;formError.value='';reason.value='';reference.value='';paidAt.value='';accountId.value='';amount.value=(value==='create'?selected.value?.commissionAmount4:null)?.replace(/(\.\d{2})\d{2}$/,'$1')||'';await nextTick();modal.value?.showModal();if(value==='create'){draftWithdrawalId.value=selectedPayout.value?.status==='REJECTED'?selectedPayout.value.id:incomeDraft.value!.withdrawalId;await loadAccounts();}}
function closeModal(){if(busy.value)return;modal.value?.close();mode.value='';}
async function refreshSelected(updated:IncomePayout){if(month.value==='UNASSIGNED'){if(selected.value?.payout?.id===updated.id)selected.value={...selected.value,status:updated.status,payout:updated};await load(page.value);return;}const id=selected.value?.promoterUserId;if(!id)return;const result=await api.loadIncome({month:month.value,status:'ALL',promoterUserId:id,page:0,size:1});if(!alive||selected.value?.promoterUserId!==id)return;selected.value=result.items[0];await load(page.value);}
function commandError(cause:unknown){
 if(cause instanceof ApiError&&[400,401,403,404,409,422].includes(cause.status)){
  const reasons:Record<string,string>={
   'withdrawal exceeds available balance':'发放金额超过当前可用佣金，请核对金额后重试',
   'available commission is insufficient or has debt':'可用佣金不足或存在佣金债务，请核对后重试',
   'cash debt must be cleared':'请先结清佣金债务，再提交发放单',
   'monthly payout already exists; reopen the rejected record':'该月已有发放单，请刷新后查看已有记录',
   'promoter is disabled':'代理已停用，无法提交此操作',
   'payout account is not active':'收款账户已停用，请重新选择',
   'payout account is unavailable':'收款账户不可用，请重新选择',
   'payout account belongs to another user':'收款账户不属于当前代理，请重新选择'
  };
  return reasons[cause.message]||({401:'登录已失效，请重新登录',403:'没有执行此操作的权限',409:'数据状态已变化，请刷新核对后重试'}[cause.status]||'提交未通过，请核对填写内容后重试');
 }
 return '操作结果暂未确认，请刷新核对后重试';
}
async function command<T=IncomePayout>(kind:string,values:Record<string,unknown>,send:(body:any)=>Promise<T>,after:(updated:T)=>Promise<void>=refreshSelected as (updated:T)=>Promise<void>){if(busy.value)return;const key=JSON.stringify([kind,month.value,selectedPayout.value?.id,selected.value?.promoterUserId,values]);const body=pending.get(key)||{commandId:crypto.randomUUID(),...values};pending.set(key,body);busy.value=true;formError.value='';detailError.value='';try{const updated=await send(body);pending.delete(key);if(!alive)return;modal.value?.close();mode.value='';try{await after(updated);}catch{if(alive)detailError.value='操作已提交，但数据刷新失败，请刷新页面核对';}}catch(e){if(alive){if(e&&typeof e==='object'&&'status'in e&&[400,409,422].includes(Number(e.status)))pending.delete(key);(mode.value?formError:detailError).value=commandError(e);}}finally{if(alive)busy.value=false;}}
async function approve(){const p=selectedPayout.value;if(!p)return;await command('approve',{approved:true,reason:null,expectedAdjustmentVersion:p.adjustmentVersion,expectedAmount4:p.finalAmount4},body=>api.decidePayout(p.id,body));}
async function submit(){const row=selected.value,p=row?.payout;if(!row)return;formError.value='';if(mode.value==='adjust'){if(!canAdjust.value||!/^(?:0|[1-9]\d*)(?:\.\d{1,2})?$/.test(amount.value)||(units4(amount.value)||0n)<=0n||(units4(adjustmentPreview.value)||0n)<=0n||!reason.value.trim()){formError.value='请填写正数调整金额与原因，调整后金额必须大于0';return;}const values={deltaAmount4:nextAdjustment.value!,reason:reason.value.trim(),expectedVersion:p?p.adjustmentVersion:incomeDraft.value!.adjustmentVersion};if(p)await command('adjust',values,body=>api.adjustPayout(p.id,body));else await command('draft',values,body=>api.saveIncomeDraft(row.promoterUserId,month.value,body),async updated=>{incomeDraft.value=updated;});}else if(mode.value==='reject'){if(!p||!reason.value.trim()){formError.value='请填写驳回原因';return;}await command('reject',{approved:false,reason:reason.value.trim(),expectedAdjustmentVersion:p.adjustmentVersion,expectedAmount4:p.finalAmount4},body=>api.decidePayout(p.id,body));}else if(mode.value==='pay'){if(!p||!reference.value.trim()||!paidAt.value||!Number.isFinite(new Date(paidAt.value).getTime())){formError.value='请填写付款流水号和实际付款时间';return;}await command('pay',{transferReference:reference.value.trim(),paidAt:new Date(paidAt.value).toISOString()},body=>api.completePayout(p.id,body));}else if(mode.value==='create'){if(!p&&!incomeDraft.value)return;if((units4(createPreview.value)||0n)<=0n){formError.value='调整后金额必须大于0';return;}if(!/^(?:0|[1-9]\d*)(?:\.\d{1,2})?$/.test(amount.value)||(units4(amount.value)||0n)<=0n||!accountId.value){formError.value='请选择收款账户并填写正数金额，最多两位小数';return;}const available=units4(row.availableAmount4);if((units4(row.debtAmount4)||0n)>0n){formError.value='请先结清佣金债务，再提交发放单';return;}if(available!==null&&units4(amount.value)!>available){formError.value='发放金额超过当前可用佣金，请核对金额后重试';return;}await command('create',{withdrawalId:draftWithdrawalId.value,promoterUserId:row.promoterUserId,settlementMonth:month.value,amount4:amount.value,payoutAccountId:accountId.value,...(!p?{expectedDraftVersion:incomeDraft.value!.adjustmentVersion}:{})},api.createPayout);}}
async function filter(nextStatus=status.value){if(busy.value)return;closeDetail();status.value=nextStatus;await load(0);}
onMounted(()=>{void load();void searchAgents();});
</script>
<template>
<section class="income-page" :class="{'has-detail':selected}" aria-label="代理月度收益">
<div class="income-main">
<header class="income-heading"><div><h2>代理月度结算</h2><p>基于下级客户的实际消费明细计算代理收益，支持人工调整与发放管理。</p></div><label>{{month==='UNASSIGNED'?'未归属月份':'归属月份'}}<input v-model="month" aria-label="收益月份" type="month" :disabled="busy" @change="filter('ALL')"></label></header>
<div class="income-stats">
  <article data-testid="monthly-consumption"><i><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M2 3h4l1 3h15l-3 10H8L5 5H2Zm7 15h10v2H9Z"/><circle cx="10" cy="22" r="1.5"/><circle cx="18" cy="22" r="1.5"/><path d="m10 9 3 2 4-3" fill="none" stroke="white" stroke-width="1.5" stroke-linecap="round"/></svg></i><div><span>本月有效消费</span><strong>{{money(snapshot?.totalConsumptionAmount4)}}</strong><small>较上月 <b data-testid="consumption-comparison" :class="changeClass(consumptionChange)">{{consumptionChange}}</b></small></div></article>
  <article><i><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="6" r="3.4"/><path d="M4 21v-2a8 6 0 0 1 16 0v2Z" fill="white"/></svg></i><div><span>待结算代理</span><strong>{{snapshot?count('UNSETTLED'):'—'}}</strong><small>较上月 <b data-testid="unsettled-comparison" :class="changeClass(unsettledChange)">{{unsettledChange}}</b></small></div></article>
  <article><i><PromoterIcon name="money"/></i><div><span>待发放收益</span><strong>{{money(snapshot?.pendingPayoutAmount4)}}</strong><small>涉及 {{snapshot?count('PENDING_PAYOUT'):'—'}} {{month==='UNASSIGNED'?'笔发放单':'家代理'}}</small></div></article>
  <article><i class="red"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m12 3 10 18H2Z" fill="white"/><path d="M12 9v5m0 3v.1"/></svg></i><div><span>异常结算</span><strong>{{snapshot?count('REJECTED'):'—'}}</strong><small>需处理</small></div></article>
</div>
<div class="income-list"><nav class="income-status" aria-label="收益状态"><button v-for="[key,label] in statuses" :key="key" :data-status="key" :aria-pressed="status===key" :disabled="busy||loading" @click="filter(key)">{{label}} <small>{{count(key!)}}</small></button></nav>
<div class="income-toolbar"><AdminSearchSelect id="income-agent-search" v-model="owner" label="搜索代理名称或手机号" :options="options" remote :loading="searching" :has-more="searchMore" :disabled="busy" @query="searchAgents($event)" @load-more="searchAgents('',true)"/><button :disabled="busy||loading" @click="filter()">查询</button><button :disabled="busy||loading" @click="owner='';filter('ALL')">重置</button><button class="income-legacy" :disabled="busy" @click="month='UNASSIGNED';filter('ALL')">未归属月份记录</button></div>
<p v-if="error" role="alert">{{error}}</p>
<div class="income-table-wrap"><table><caption class="sr-only">代理收益列表</caption><thead><tr><th>代理名称</th><th>手机号</th><th>下级客户数</th><th>消费订单数</th><th class="income-consumption-heading">本月消费金额</th><th>分佣比例</th><th>应发收益</th><th>调整金额</th><th>实发收益</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in snapshot?.items||[]" :key="r.payout?.id||r.promoterUserId" :class="{'is-selected':selected===r}"><td><strong>{{name(r.promoterUserId)}}</strong></td><td>{{phone(r.promoterUserId)}}</td><td>{{r.downlineCount??'—'}}</td><td>{{r.consumptionCount??'—'}}</td><td :title="r.consumptionAmount4||''">{{money(r.consumptionAmount4)}}</td><td>{{rate(r.promoterUserId)}}</td><td>{{money(r.payout?.baseAmount4)}}</td><td :class="{'positive':(units4(r.payout?.adjustmentAmount4)||0n)>0n,'negative':(units4(r.payout?.adjustmentAmount4)||0n)<0n}">{{money(r.payout?.adjustmentAmount4)}}</td><td>{{money(r.payout?.finalAmount4)}}</td><td><span class="income-badge" :class="r.status">{{statusName(r.status)}}</span></td><td><button class="income-link" :aria-label="`查看${name(r.promoterUserId)}收益`" :disabled="busy" @click="open(r,$event)">查看</button></td></tr><tr v-if="!snapshot?.items.length"><td colspan="11" class="income-empty">{{loading?'正在读取…':'暂无记录'}}</td></tr></tbody></table></div>
<nav class="income-pagination" aria-label="代理收益分页"><span>共 {{snapshot?.total||0}} 条</span><div><button :disabled="!page||loading||busy" @click="load(page-1)">‹</button><button v-for="n in pages" :key="n" :aria-current="n===page?'page':undefined" :disabled="loading||busy" @click="load(n)">{{n+1}}</button><button aria-label="下一页代理收益" :disabled="page+1>=totalPages||loading||busy" @click="load(page+1)">›</button></div><select v-model.number="size" aria-label="每页代理收益条数" :disabled="loading||busy" @change="load(0)"><option :value="10">10 条/页</option><option :value="20">20 条/页</option><option :value="50">50 条/页</option></select></nav></div>
</div>
<aside v-if="selected" class="income-drawer" aria-label="收益详情" @keydown.esc.stop="closeDetail"><button id="income-close-detail" class="income-close" aria-label="关闭收益详情" :disabled="busy" @click="closeDetail">×</button><header class="income-profile"><span class="income-avatar">{{name(selected.promoterUserId).slice(0,1)}}</span><div><h3>{{name(selected.promoterUserId)}} <span class="income-badge" :class="selected.promoterStatus==='ENABLED'?'PAID':'REJECTED'">{{selected.promoterStatus==='ENABLED'?'正常':'停用'}}</span></h3><p>{{phone(selected.promoterUserId)}} · {{date(selected.createdAt).slice(0,10)}}</p></div><button class="income-link" :disabled="busy||!entryId||selected.promoterStatus!=='ENABLED'" @click="enter">查看代理后台 ↗</button></header>
<nav class="income-tabs" aria-label="收益详情栏目"><button v-for="[key,label] in tabs" :key="key" :aria-pressed="tab===key" :disabled="busy" @click="switchTab(key!)">{{label}}</button></nav><p v-if="detailError" role="alert">{{detailError}}</p>
<template v-if="tab==='settlement'"><section class="income-section"><h4>收益计算</h4><div class="income-calculation"><div><small>本月有效消费</small><strong>{{money(selected.consumptionAmount4)}}</strong></div><span>{{historicalRates.length===1&&historicalRates[0]!==null?'×':'按'}}</span><button class="income-history-rates" data-testid="historical-rates" @click="switchTab('consumption')"><small>历史分佣比例</small><strong>{{historicalRateText}}</strong></button><span>=</span><div><small>消费佣金</small><strong>{{money(selected.commissionAmount4)}}</strong></div></div><div class="income-result"><article class="income-adjustment-card"><small>人工调整</small><div class="income-adjustment-summary"><strong :class="{'positive':(units4(adjustmentAmount)||0n)>0n,'negative':(units4(adjustmentAmount)||0n)<0n}">{{(units4(adjustmentAmount)||0n)>0n?'+ ':''}}{{money(adjustmentAmount)}}</strong><button class="income-link income-records" :data-testid="canAdjust?'open-adjustment':undefined" :disabled="busy||draftLoading" @click="canAdjust?openModal('adjust'):switchTab('adjustments')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m15 4 5 5M4 20l4-1L20 7a2 2 0 0 0-3-3L5 16l-1 4Zm0 0h15"/></svg>调整记录</button></div></article><article><small>实发收益</small><strong class="income-final">{{money(finalAmount)}}</strong></article></div></section>
<section class="income-section"><h4>代理信息</h4><dl><div><dt>代理名称</dt><dd>{{name(selected.promoterUserId)}}</dd></div><div><dt>代理状态</dt><dd>{{selected.promoterStatus==='ENABLED'?'正常':'停用'}}</dd></div><div><dt>下级客户数</dt><dd>{{selected.downlineCount??'—'}}</dd></div><div><dt>加入时间</dt><dd>{{date(selected.createdAt)}}</dd></div><div><dt>当前可用佣金</dt><dd>{{money(selected.availableAmount4)}}</dd></div><div><dt>佣金债务</dt><dd>{{money(selected.debtAmount4)}}</dd></div></dl></section>
<section class="income-section"><h4>收款账户</h4><template v-if="selectedPayout"><p>{{selectedPayout.payoutType==='BANK_CARD'?'银行卡':selectedPayout.payoutType==='ALIPAY'?'支付宝':'微信'}} · {{selectedPayout.maskedAccountName}}</p><p>{{fullAccount?.accountReference||selectedPayout.maskedAccountReference}} <button class="income-link" :disabled="busy" @click="reveal">{{fullAccount?'刷新完整账号':'查看完整账号'}}</button></p><p v-if="fullAccount">{{fullAccount.accountName}} · {{fullAccount.bankName}}</p></template><p v-else>尚未创建发放单</p></section>
<section class="income-section"><h4>本月消费汇总</h4><div class="income-calculation"><div><small>下级客户数</small><strong>{{selected.downlineCount??'—'}}</strong></div><div><small>消费订单数</small><strong>{{selected.consumptionCount??'—'}}</strong></div><div><small>总消费金额</small><strong>{{money(selected.consumptionAmount4)}}</strong></div></div></section>
<footer class="income-actions"><template v-if="selectedPayout?.status==='WITHDRAWING'"><button :disabled="busy" @click="openModal('reject')">驳回</button><button class="primary" data-testid="approve-income" :disabled="busy" @click="approve">审核通过</button></template><template v-else-if="selectedPayout?.status==='PENDING_PAYOUT'"><button :disabled="busy" @click="closeDetail">暂缓发放</button><button class="primary" data-testid="open-payment" :disabled="busy" @click="openModal('pay')">确认发放</button></template><button v-else-if="month!=='UNASSIGNED'&&selectedPayout?.status!=='PAID'" class="primary" :disabled="busy||selected.promoterStatus!=='ENABLED'||(!selectedPayout&&(!incomeDraft||draftLoading))" @click="openModal('create')">{{selectedPayout?'重新提交发放单':'创建发放单'}}</button><span v-else-if="selectedPayout?.status==='PAID'">已发放 · {{date(selectedPayout.paidAt)}}</span></footer></template>
<section v-else class="income-section income-detail-table"><div v-if="detailLoading" class="income-empty">正在读取…</div><table v-else-if="tab==='consumption'"><thead><tr><th>客户 / 时间</th><th>消费金额</th><th>比例</th><th>佣金</th></tr></thead><tbody><tr v-for="r in consumptionRows" :key="r.allocationId"><td>{{name(r.customerUserId)}}<small>{{date(r.occurredAt)}}</small></td><td>{{money(r.paidAmount4)}}</td><td>{{r.cashRate6===null?'—':`${Number(r.cashRate6)*100}%`}}</td><td>{{money(r.commissionAmount4)}}</td></tr></tbody></table><table v-else-if="tab==='adjustments'"><thead><tr><th>时间 / 操作人</th><th>调整后净额</th><th>原因</th><th>状态</th></tr></thead><tbody><tr v-for="r in adjustmentRows" :key="r.commandId"><td>{{date(r.occurredAt)}}<small>{{name(r.operatorId)}}</small></td><td>{{money(r.deltaAmount4)}}</td><td>{{r.reason}}</td><td>{{r.status==='APPROVED'?'已生效':r.status==='REJECTED'?'未通过':r.status==='SUPERSEDED'?'已替代':'待审核'}}</td></tr></tbody></table><table v-else><thead><tr><th>月份 / 时间</th><th>发放金额</th><th>状态 / 流水号</th></tr></thead><tbody><tr v-for="r in historyRows" :key="r.id"><td>{{r.settlementMonth||'未归属月份'}}<small>{{date(r.paidAt||r.requestedAt)}}</small></td><td>{{money(r.finalAmount4)}}</td><td>{{statusName(r.status)}}<small>{{r.transferReference||'—'}}</small></td></tr></tbody></table><p v-if="!detailLoading&&!detailTotal" class="income-empty">暂无记录</p><nav class="income-pagination"><button :disabled="!detailPage||detailLoading" @click="switchTab(tab,detailPage-1)">上一页</button><span>共 {{detailTotal}} 条</span><button :disabled="(detailPage+1)*10>=detailTotal||detailLoading" @click="switchTab(tab,detailPage+1)">下一页</button></nav></section>
</aside>
<dialog v-if="mode" ref="modal" class="income-modal" :aria-label="mode==='pay'?'确认发放收益':mode==='adjust'?'人工调整收益':mode==='reject'?'驳回发放单':'创建发放单'" @cancel.prevent="closeModal"><form @submit.prevent="submit"><header><h3>{{mode==='pay'?'确认发放收益':mode==='adjust'?'人工调整收益':mode==='reject'?'驳回发放单':'创建发放单'}}</h3><button type="button" aria-label="关闭操作窗口" :disabled="busy" @click="closeModal">×</button></header><dl><div><dt>代理名称</dt><dd>{{selected?name(selected.promoterUserId):''}}</dd></div><div><dt>{{mode==='create'?'本月消费佣金':'实发金额'}}</dt><dd class="income-final">{{money(mode==='create'?selected?.commissionAmount4:finalAmount)}}</dd></div><div v-if="mode==='create'"><dt>当前可用佣金</dt><dd>{{money(selected?.availableAmount4)}}</dd></div></dl>
<template v-if="mode==='pay'"><p>{{selectedPayout?.maskedAccountName}} · {{selectedPayout?.maskedAccountReference}}</p><label>付款流水号<input v-model="reference" aria-label="付款流水号" maxlength="256" :disabled="busy"></label><label>实际付款时间<input v-model="paidAt" aria-label="实际付款时间" type="datetime-local" :disabled="busy"></label></template>
<template v-else-if="mode==='adjust'"><label>调整方向<select v-model="direction" aria-label="调整方向" :disabled="busy"><option value="add">增加</option><option value="subtract">减少</option></select></label><label>人工调整金额<input v-model="amount" aria-label="人工调整金额" inputmode="decimal" :disabled="busy"></label><label>调整原因<textarea v-model="reason" aria-label="调整原因" maxlength="2000" :disabled="busy"/></label><p data-testid="adjustment-preview">调整后收益 <strong>{{money(adjustmentPreview)}}</strong></p><button type="button" class="income-link" :disabled="busy" @click="closeModal();switchTab('adjustments')">查看调整记录</button></template><label v-else-if="mode==='reject'">驳回原因<textarea v-model="reason" aria-label="驳回原因" maxlength="2000" :disabled="busy"/></label>
<template v-else><label>基准发放金额<input v-model="amount" aria-label="发放金额" inputmode="decimal" :disabled="busy"></label><label>收款账户<select v-model="accountId" aria-label="收款账户" :disabled="busy"><option value="">请选择</option><option v-for="r in accountRows" :key="r.id" :value="r.id">{{r.bankName||r.payoutType}} · {{r.maskedPayoutAccountName}} · {{r.maskedPayoutAccountReference}}</option></select></label><button v-if="(accountPage+1)*10<accountTotal" type="button" :disabled="busy" @click="loadAccounts(true)">更多账户</button></template><p v-if="mode==='create'" data-testid="create-final-preview">实发收益 <strong>{{money(createPreview)}}</strong></p><p v-if="formError" role="alert">{{formError}}</p><footer><button type="button" :disabled="busy" @click="closeModal">取消</button><button type="submit" class="primary" :data-testid="mode==='pay'?'confirm-payment':mode==='adjust'?'save-adjustment':'submit-income'" :disabled="busy">{{busy?'处理中…':mode==='pay'?'确认发放':mode==='adjust'?'提交调整':mode==='reject'?'确认驳回':'提交审核'}}</button></footer></form></dialog>
</section>
</template>
